const MUNAJAT_DATA = [{"id": "munajat-۱", "text": "یارب دل پاک و جان آگاهم ده"}, {"id": "munajat-۲", "text": "الهی نام تو ما را جواز، مهر تو ما را جهاز، شناخت تو ما را امان، لطف تو ما را عیان"}, {"id": "munajat-۳", "text": "الهی ضعیفان را پناهی، قاصدان را بر سر راهی، مومنان را گواهی، چه عزیز است آنکس که تو خواهی"}, {"id": "munajat-۴", "text": "الهی ای خالق بی مدد و ای واحد بی عدد، ای اول بی هدایت و ای آخر بی نهایت ای ظاهر بی صورت وای باطن بی سیرت، ای حی بی ذلت ای مُعطی بی فطرت و ای بخشندهٔ بی منت، ای دانندهٔ راز ها، ای شنونده آواز ها، ای بینندهٔ نماز ها، ای شناسندهٔ نامها، ای رسانندهٔ گامها، ای مُبّرا از عوایق، ای مطلع برحقایق، ای مهربان بر خلایق عذر های ما بپذیر که تو غنی و ما فقیر و بر عیبهای ما مگیر که تو قوی و ماحقیر، از بنده خطا آید و ذلت و از تو عطا آید و رحمت"}, {"id": "munajat-۵", "text": "الهی ای کامکاری که دل دوستان در کنف توحید تو است و ای ار گذاری که جان بندگان در صدف تقدیر تواست، ای قهاری که کس را بتو حیلت نیست، ای جباری که گردنکشان را با تو روی مقاومت نیست، ای حکیمی روندگان ترا از بلای تو گریز نیست، ای کریمی که بندگان را غِیر از تو دست آویز نیست، نگاه دار تا پریشان نشویم و در راه آر تا سر گر دان نشویم"}, {"id": "munajat-۶", "text": "الهی در جلال رحمانی، در کمال سبحانی، نه محتاج زمانی، و نه آرزومند مکانی، نه کس بتو ماند و نه به کسی مانی، پیداست که در میان جانی، بلکه جان زنده بچیزی است که تو آنی"}, {"id": "munajat-۷", "text": "الهی کجا باز یابیم آنروز که تو ما را بودی و من نبودم، تا باز به آن روز رسم میان آتش و دودم اگر بدو کیستی آن روز یابم پُر سودم و ربود خود را یابم به نبود خود خشنودم"}, {"id": "munajat-۸", "text": "الهی از آنچه نخواستی چه آید، و آنرا که نخواندی کی آید، نا کشته را از آب چیست، و ناخوانده را جواب چیست، تلخ را چه سود اگرش آب خوش در جوار است و خار را چه حاصل از آنکه بوی گل در کنار است"}, {"id": "munajat-۹", "text": "الهی هر آه ترا شناخت و علم مهر تو افراخت هر چه غیر از تو بود بینداخت"}, {"id": "munajat-۱۰", "text": "الهی هر که ترا شناسد کار او باریک و هر که ترا نشناسد راه او تاریک، تو را شناختن از تو رستن است و بتو پیوستن از خود گذشتن است"}, {"id": "munajat-۱۱", "text": "الهی بر من آراستی خریدم و از هر دو جهان دوستی حضرت تو گُزیدم"}, {"id": "munajat-۱۲", "text": "الهی اگر طاعت بسی ندارم در هر جهان جز تو کسی ندارم"}, {"id": "munajat-۱۳", "text": "الهی تا بتو آشنا شدم از خلق جدا شدم و در هر جهان شیدا شدم نهان بودم پیدا شدم"}, {"id": "munajat-۱۴", "text": "الهی از بنده با حکم ازل چه برآید و بر آنچه ندارد چه باید. کوشش بنده چیست؟ کار خواست تو دارد، بجهد خویش نجات خویش کی تواند"}, {"id": "munajat-۱۵", "text": "الهی ای سزای کرم و ای نوازندهٔ عالم، نه بآخر شادیست نه با یاد تو غم، خصمی و شفیعی و گواهی و حَکَم"}, {"id": "munajat-۱۶", "text": "الهی تو دوستان را بدشمنان می نمایی، درویشان را غم و اندوه دهی، بیمار کنی و خود بیمارستان کنی، درمانده کنی و خود درمان کنی، از خاک آدم کنی و بادی چندان احسان کنی"}, {"id": "munajat-۱۷", "text": "الهی از پیش خطر و از پس راهم نیست، دستم گیر که جز تو پناهم نیست"}, {"id": "munajat-۱۸", "text": "الهی دستم گیر که دست آویز ندارم، و عذرم بپذیر که پای گریز ندارم"}, {"id": "munajat-۱۹", "text": "الهی خود را از همه بتو وابستم، اگر بداری ترا پرستم و اگر نداری خود پرستم نومید مساز بگیر دستم"}, {"id": "munajat-۲۰", "text": "الهی ای دور نظر وای نیکو حضر و ای نیکو کار نیک منظر، ای دلیل هر برگشته، و ای راهنمای هر سر گشته، ای چاره ساز هر بیچاره و ای آرندهٔ هر آواره، ای جامع هر پراکنده و ای رافع هر افتاده دست ما گیر ای بخشنده بخشاینده"}, {"id": "munajat-۲۱", "text": "الهی کار آن دارد که با تو کاری دارد، یار آن دارد که چون تو یاری دارد، او که در هر دو جهان ترا دارد هر گز کی تو را بگذارد"}, {"id": "munajat-۲۲", "text": "الهی در سر گریسنی دارم دراز، ندانم از حسرت گریم یا از ناز"}, {"id": "munajat-۲۳", "text": "الهی یک چند بیاد تو نازیدم، اینم بس که صحبت تو ارزیدم"}, {"id": "munajat-۲۴", "text": "الهی نه جز از یاد تو دل است نه جز از یافت تو جان، پس بیدل و بی جان کی توان"}, {"id": "munajat-۲۵", "text": "الهی یاد تو در میان دل و زبان است و مهر تو میان سر و جان"}, {"id": "munajat-۲۶", "text": "الهی شاد بدانیم که اول تو بودی و ما نبودیم، کار تو در گرفتی و ما نگرفتیم، قسمت خود نهادی و رسول خود فرستادی"}, {"id": "munajat-۲۷", "text": "الهی هر چه بی طلب بما دادی بسزا واری ما تباه مکن، و هر چه بجای ناکرد از نیکی بعیب ما از ما بریده مکن و هر چه سزای ما ساختی بنا بسزایی ما جدا مکن"}, {"id": "munajat-۲۸", "text": "الهی آنچه ما خود کشتیم به بر میار و آنچه تو ما را کشتی آفت ما از آن باز دار"}, {"id": "munajat-۲۹", "text": "الهی از نزدیک نشانت می دهند و بر تر از آنی و دورت پندارند و نزدیکتر از جانی موجود نفسهای جوانمردانی، حاضر دلهای ذاکرانی، ملکا تو آنی که خود گفتی و چنانکه گفتی آنی"}, {"id": "munajat-۳۰", "text": "الهی در این درگاه همه ما نیازمند روزی باشیم که قطره یی از شراب محبت بر دل ما ریزی تا که ما را بر آب و آتش بر هم آمیزی"}, {"id": "munajat-۳۱", "text": "الهی دیگران مست شرابند و من مست ساقی، مستی ایشان فانی است و از من باقی"}, {"id": "munajat-۳۲", "text": "الهی روزگاری ترا می جستم خود را می یافتم، اکنون خود را میجویم و ترا می یابم"}, {"id": "munajat-۳۳", "text": "الهی تا از مهر تو اثر آمد، دیگر مهر ما بسر آمد"}, {"id": "munajat-۳۴", "text": "الهی ای مهربان فریاد رس، عزیز آن کس که او با تو یک نفس، نفسی که آنرا حجاب ناید از پس"}, {"id": "munajat-۳۵", "text": "الهی گهی بخود نگرم گویم از من زار تر کیست، گهی بتو نگرم گویم از من بزرگوار تر کیست"}, {"id": "munajat-۳۶", "text": "الهی ای سزای کرم، ای نوازندهٔ عالم، نه با وصل تو اندوه است و نه با یاد تو غم"}, {"id": "munajat-۳۷", "text": "الهی ادای شکر ترا هیچ زبان نیست و دریای فضل ترا هیچ کران نیست و سر حقیقت تو بر هیچکس عیان نیست، هدایت کن بر ما رهی که بهتر از آن نیست"}, {"id": "munajat-۳۸", "text": "الهی ما از غافلانیم نه از کافرانیم، نگاهدار تا پریشان نشویم و در راه آر تا سرگردان نشویم"}, {"id": "munajat-۳۹", "text": "الهی پسندیدگان ترا بتو جستند و به تو پیوستند، نا پسندیدگان تو را بخود جستند و بگسستند نه او که پیوست بشکر رسید، نه او که گسست بعذر رسید"}, {"id": "munajat-۴۰", "text": "الهی این همه نوازش از تو بهرهٔ ما ست که در هر نفس چندین سوز و نور غایت تو پیداست چون تو مولایی کراست؟ و چون تو دوست کجاست"}, {"id": "munajat-۴۱", "text": "الهی خود کردم و خود خریدم، آتش بر خود، خود افروزانیدم، از دوستی آواز دادم دل و جان را فراناز دادم، اکنون که در غرقابم دستم گیر که گرم افتادم"}, {"id": "munajat-۴۲", "text": "الهی چه یاد کنم که خود همه یادم، من خرمن نشان خود فرا باد دادم"}, {"id": "munajat-۴۳", "text": "الهی چندی به کسب تو یاد تو ورزیدم، باز یک چندی بیاد خود را نازیدم، اکنون که یاد بشناختم خاموش گردیدم"}, {"id": "munajat-۴۴", "text": "الهی کار آن کس کند که تواند، عطا آن کس بخشد که دارد، پس بنده چه تواند و چه دارد"}, {"id": "munajat-۴۵", "text": "الهی تو دوختی من در پوشیدم و آنچه در جام ریختی نوشیدم هیچ نیاید از آنچه کوشیدم"}, {"id": "munajat-۴۶", "text": "الهی چون تو توانایی کرا توان است، در ثناء تو کرا زبان است و بی مهر تو کرا سر و جان است"}, {"id": "munajat-۴۷", "text": "الهی بشناخت تو زندگانیم، به نصرت تو شادانیم، بکرامت تو نازانیم و بعزت تو عزیزانیم"}, {"id": "munajat-۴۸", "text": "الهی ما بتو زنده ایم هرگز کی میریم، ما که بتو شادمانیم کی اندوهگین شویم، ما که بتو نازانیم چون بی تو بسر آریم، ما که بتو عزیزیم هرگز چون ذلیل شویم"}, {"id": "munajat-۴۹", "text": "الهی چه غم دارد که تو را دارد و کرا شاید که تو را نستاید، آزادا آن نفس که بیاد تو بازان و آباد آن دل که بمهر تو نازان و شاد آن کس که با تو در پیمان است"}, {"id": "munajat-۵۰", "text": "الهی هر که تو را جوید اینقدر راستخیزی باید یا به تیغ ناکامی او را خون ریزی باید هر که قصد تو کند روزش چنین است یا بهرهٔ درویش خود چنین است"}, {"id": "munajat-۵۱", "text": "الهی همگان در فراق می سوزند و دوستدار در دیدار، چون دوست دیده ور گشت دوستدار را شکیبایی چه کار"}, {"id": "munajat-۵۲", "text": "الهی با بهشت چه سازم و با حور چه بازم، مرا دیده یی ده که از هر نظری بهشتی سازم"}, {"id": "munajat-۵۳", "text": "الهی گُل بهشت در چشم عارفان خار است و جویندهٔ تو را با بهشت چکار است"}, {"id": "munajat-۵۴", "text": "الهی اگر بهشت چشم و چراغ است بی دیدار تو درد و داغ است"}, {"id": "munajat-۵۵", "text": "الهی بهشت بی دیدار تو زندان است و زندانی بزندان برون نه کار کریمان است"}, {"id": "munajat-۵۶", "text": "الهی اگر بدوزخ فرستی دعوی دار نیستم و اگر به بهشت فرمایی بی جمال تو خریدار نیستم. مطلوب ما بر آر که جز وصال تو طلبکار نیستم"}, {"id": "munajat-۵۷", "text": "الهی تو ما را جاهل خواندی از جاهل جُز خطا چه آید؟ تو ما را ضعیف خواندی از ضعیف جُز خطا چه آید"}, {"id": "munajat-۵۸", "text": "الهی تو ما را برگرفتی و کسی نگفت که بر دار، اکنون که بر گرفتی وا مگذار و در سایهٔ لطف و عنایت خود میدار"}, {"id": "munajat-۵۹", "text": "الهی عارف تو را بنور تو میداند و از شعاع وجود عبارت نمی تواند، موحد تو را بنور قُرب می شناسد و در آتش می سوزد"}, {"id": "munajat-۶۰", "text": "الهی دانی چه شادم، نه آنکه بخویشتن بتو افتادم، تو خواستی من نخواستم، دولت بر بالین دیدم چون از خواب بر خاستم"}, {"id": "munajat-۶۱", "text": "الهی چون من کیست که اینکار را سزیدم، اینم بس محبت ترا ارزیدم"}, {"id": "munajat-۶۲", "text": "الهی از آن خوان که بهر پاکان نهادی نصیب من بینوا کو، اگر نعمتت جُز بطاعت نباشد پس آنرا بیع خوانند لطف و عطا کو؟"}, {"id": "munajat-۶۳", "text": "الهی یک دل پُر درد دارم و یک جان پُر زجر، خداوندا این بیچاره را چه تدبیر"}, {"id": "munajat-۶۴", "text": "الهی هر کس را آتش در دل است و این بیچاره آتش بر جان، از آنست که هر کس را سرو سامانی است و این درویش را نه سر و نه سامان"}, {"id": "munajat-۶۵", "text": "الهی موجود نفسهای جوانمردانی، حاضر ذاکرانی، از نزدیک نشانت میدهند و بر تر از آنی و از دورت می پندارند نزدیکتر از جانی"}, {"id": "munajat-۶۶", "text": "الهی دلی ده که شوق طاعت افزون کند و توفیق طاعتی ده که ببهشت رهنون کند"}, {"id": "munajat-۶۷", "text": "الهی نفسی ده که حلقهٔ بندگی تو گوش کند و جانی ده که زهر حکمت تو نوش کند"}, {"id": "munajat-۶۸", "text": "الهی دانایی ده که در راه نیفتیم و بینایی ده که در چاه نیفتیم"}, {"id": "munajat-۶۹", "text": "الهی دیدهٔ ده که جز تماشای ربوبیت نه بیند و دلی ده که غیر از مهر عبودیت تو"}, {"id": "munajat-۷۰", "text": "الهی پایی ده که با آن کوی مهر تو پوییم و زبانی ده که با آن شکر آلای تو گوییم"}, {"id": "munajat-۷۱", "text": "الهی در آتش حسرت آویختیم چون پروانه در چراغ، نه جان رنج دیده نه دل اَلَم داغ"}, {"id": "munajat-۷۲", "text": "الهی در سر آب دارم، در دل آتش، در باطن ناز دارم، در باطن خواهش، در دریایی نشستم که آنرا کران نیست"}, {"id": "munajat-۷۳", "text": "الهی ای کریمی که بخشندهٔ عطایی و ای حکیمی که پوشندهٔ خطایی و ای احدی که در ذات و صفات بی همتایی"}, {"id": "munajat-۷۴", "text": "الهی ای بینندهٔ نماز ها، ای پذیرندهٔ نیاز ها، ای دانندهٔ راز ها و ای شنوندهٔ آواز ها، عذر های ما بپذیر که تو غنی و ما فقیر"}, {"id": "munajat-۷۵", "text": "الهی بحق آنکه ترا هیچ حاجت نیست رحمت کن بر آنکه او را هیچ حجت نیست"}, {"id": "munajat-۷۶", "text": "الهی در دل ما جُز محبت مکار و بر این جانها جز الطاف و مرحمت مدار و بر این کشت ها جُز باران رحمت مبار"}, {"id": "munajat-۷۷", "text": "الهی تو بر رحمت خود و من بر حاجت خویش پس تو توانگری و من درویش"}, {"id": "munajat-۷۸", "text": "الهی بر هر که داغ محبت خود نهادی، خرمن وجودش را بباد نیستی در دادی"}, {"id": "munajat-۷۹", "text": "الهی همه آتشها بی محبت تو سرد است و همه نعمتها بی لطف تو درد است"}, {"id": "munajat-۸۰", "text": "الهی مخلصان بمحبت تو مینازند و عاشقان بسوی تو میتازند"}, {"id": "munajat-۸۱", "text": "الهی محبت تو گُلی است محنت و بلا خار آن، آن کدام دل است که نیست گرفتار آن"}, {"id": "munajat-۸۲", "text": "الهی از هر دو جهان محبت تو گزیدم و جامهٔ بلا بُریدم و پردهٔ عافیت دریدم"}, {"id": "munajat-۸۳", "text": "الهی چون در تو نگرم از جمله تاجدارانم و تاج بر سر و چون در خود نگرم از جملهٔ خاکسارانم و خاک بر سر"}, {"id": "munajat-۸۴", "text": "الهی مرا دل بهر تو در کار است وگر نه مرا با دل چکار است، آخر چراغ مرده را چه مقدار است"}, {"id": "munajat-۸۵", "text": "الهی تا بتو آشنا شدم، از خلق جدا شدم، در دو جهان شیدا شدم، نهان بودم و پیدا شدم"}, {"id": "munajat-۸۶", "text": "الهی اگر مستم و اگر دیوانه ام از مقیمان این آستانه ام، آشنایی با خود ده که از کاینات بیگانه ام"}, {"id": "munajat-۸۷", "text": "الهی در سر خمار تو داریم در دل اسرار تو داریم و بزبان اشعار تو داریم"}, {"id": "munajat-۸۸", "text": "الهی بر عجز خود آگاهم و بر بیچارگی خود گواهم، خواست خواست تو است من چه خواهم"}, {"id": "munajat-۸۹", "text": "الهی بروز کار آمدم بنده وار با لب پُر توبه و زبان پُر استغفار"}, {"id": "munajat-۹۰", "text": "الهی اگر خامم پخته ام کن و اگر پخته ام سوخته ام کن"}, {"id": "munajat-۹۱", "text": "الهی از کُشتهٔ تو خون نیاید و از سوختهٔ تو درد، کُشتهٔ تو بکُشتن شاد است و سوختهٔ تو بسوختن خوشنود"}, {"id": "munajat-۹۲", "text": "الهی روی بنما تا در روی کسی ننگریم و دری بگشی تا بر در کس نگُذریم"}, {"id": "munajat-۹۳", "text": "الهی بحرمت ذاتی که تو آنی، بحرمت صفاتی که چنانی و بحرمت نامی که تتو دانی بفریاد رس که میتوانی"}, {"id": "munajat-۹۴", "text": "الهی مکُش این چراغ افروخته را مُسوز این دل سوخته را و مَدَر این پردهٔ دوخته را و مران این بندهٔ نو آموخته را"}, {"id": "munajat-۹۵", "text": "الهی اگر تن مجرم است دل مطیع است و اگر بنده بد کار است کَرَم تو شفیع است"}, {"id": "munajat-۹۶", "text": "الهی قبلهٔ عارفان خورشید روی تو است و محراب جانها طاق ابروی تو است و مسجد اقصی دلها حریم کوی تو است، نظری بسوی ما فرما که نظر ما بسوی تو است"}, {"id": "munajat-۹۷", "text": "الهی بنام آن خدایی که نام او راحت روح است و پیغام او مفتاح فتوح، عذر های ما بپذیر و بر عیب ما مگیر"}, {"id": "munajat-۹۸", "text": "الهی اقرار کردم بمفلسی و هیچ کسی، ای یگانه که از هر چیز مقدّسی چه شود اگر مفلسی را در نفس آخر بفریاد رسی"}, {"id": "munajat-۹۹", "text": "الهی از هیچ همه چیز توانی و از همه چیز بهیچ نمایی که گویم چنین یا چنانی تو آفرینندهٔ این و آنی"}, {"id": "munajat-۱۰۰", "text": "الهی ای آنکه گردون رام تقدیر تو است و رقبهٔ عالمیان مسخر تدبیر تو است، در دلها پنهان تو، در آخرت عیان تو که عبدالله عذر بکاست اما غذر نخواست"}, {"id": "munajat-۱۰۱", "text": "الهی بفضل خود قایمی و بشکر خود شکور، بعلم عارف نزدیکی و از وهمها همه دور"}, {"id": "munajat-۱۰۲", "text": "الهی عبدالله را از سه آفت نگاه دار از وساوس شیطانی و خواهشهای نفسانی و غرور نادانی"}, {"id": "munajat-۱۰۳", "text": "الهی اگر عبدالله را خواهی گداخت دوزخی باید پالایش او را و اگر خواهی نواخت بهشت دیگر باید آرایش او را"}, {"id": "munajat-۱۰۴", "text": "الهی کاشکی عبدالله خاک بودی تا نامش از دفتر وجود پاک بودی"}, {"id": "munajat-۱۰۵", "text": "الهی اگر کاسنی تلخست از بوستان است و اگر عبدالله مُجرمست از دوستان است"}, {"id": "munajat-۱۰۶", "text": "الهی چون آتش فراق داشتی دوزخ پُر آتش از چه افراشتی"}, {"id": "munajat-۱۰۷", "text": "الهی چون سگ را در این درگاه بار است و سنگر او دیدار است عبدالله را با نا امیدی چه کار است"}, {"id": "munajat-۱۰۸", "text": "الهی گوهر اصطفا در دامن آدم تو ریختی و گرد عصیان بر فرق ابلیس تو بیختی و این دو جنس مخالف را با هم آمیختی"}, {"id": "munajat-۱۰۹", "text": "الهی تو دوختی در پوشیدم و آنچه در جام ریختی نوشیدم هیچ نیامد از آنچه میکوشیدم"}, {"id": "munajat-۱۱۰", "text": "الهی من غلام آن معصیتم که مرا بعذر آرد و ازآن طاعت بیزارم که مرا تعجُب آرد"}, {"id": "munajat-۱۱۱", "text": "الهی گدای تو بکار خود شادان است، هر که گدای تو شد در دو عالم سلطان است"}, {"id": "munajat-۱۱۲", "text": "الهی غیر از المهای تو جای شادی نیست و جُز از بندگیت روی آزادی نیست"}, {"id": "munajat-۱۱۳", "text": "الهی کار اگر بگفتار است بر سر همه گویندگان تاجم و اگر بکردار است چون سلیمان بموری محتاجم"}, {"id": "munajat-۱۱۴", "text": "الهی کدام درد بود ازین بیش که معشوق توانگر و عاشق درویش"}, {"id": "munajat-۱۱۵", "text": "الهی من کیستم که ترا خواهم چون از قیمت خود آگاهم، از هر چه می پندارم کمترم و از هر دمی که می شمارم بد ترم"}, {"id": "munajat-۱۱۶", "text": "الهی بر سر از خجالت گرد داریم و در دل از حسرت درد داریم و رُخ از شرم گناه زرد داریم"}, {"id": "munajat-۱۱۷", "text": "الهی از مدت ارزومندی روزی ماند و از درد فراق بدل سوزی ماند"}, {"id": "munajat-۱۱۸", "text": "الهی از یادگار فردی ماند و از عُمر گذشته دردی ماند و از جسم پوسیده گردی و از حسرت بسینه آه سردی"}, {"id": "munajat-۱۱۹", "text": "الهی اگر توبه به بیگناهی است پس در این جهان تایب کیست و اگر به پشیمانی است پس در جهان عاصی کیست"}, {"id": "munajat-۱۲۰", "text": "الهی صبر از من رمید و طاقت من شد سُست، تخم آرام کشتم بیقراری رُست، نه خُرسندم نه صبور و مهجورم نه رنجور"}, {"id": "munajat-۱۲۱", "text": "الهی تو منزلی و دوستان تو در راه پس نه دل عذر خواه است و نه زبان کوتاه"}, {"id": "munajat-۱۲۲", "text": "الهی خلق بشادی از بلا برهند، من بشادی مبتلا شدم، همه شادی بخود رسانند من ترا یکتا شدم"}, {"id": "munajat-۱۲۳", "text": "الهی گردن گردون رام تقدیر تو است و رقبهٔ علمیان مسخّر تدبیر تو است، سر سر کشان بستهٔ تو و جباران کُشتهٔ تو"}, {"id": "munajat-۱۲۴", "text": "الهی شراب شوق در جان منصور حلاّج افزون شد، آن شراب در آن نگنجید سر بیرون شد"}, {"id": "munajat-۱۲۵", "text": "الهی فراق کوه را هامون کند، هامون را جیحون کند، حیحون را پر خون کند، دانی که با این دل ضعیف چون کند"}, {"id": "munajat-۱۲۶", "text": "الهی نظر خود بر ما مدام کن و این شادی خود بر ما تمام کن، بوقت رفتن بر جان ما سلام کن"}, {"id": "munajat-۱۲۷", "text": "الهی همه از حیرت بفریادند و من از حیرت شادم، به یک لحظه درب همه ناکامی بر خود بگشادم"}, {"id": "munajat-۱۲۸", "text": "الهی پیوسته در گفت و گویم، تا وا ننمایی در جست و جویم"}, {"id": "munajat-۱۲۹", "text": "الهی مرکب وا ایستاد و قدرم بفرسود، همراهان برفتند و این بیچاره را جُز حیرت نیفزود"}, {"id": "munajat-۱۳۰", "text": "الهی اگر کسی تو را به جُستن یافت من ترا بگریختن یافتم، خدایا وسیلت به تو هم تویی، اول تو بودی و آخر هم تویی"}, {"id": "munajat-۱۳۱", "text": "الهی ای مهیمن اکرم، ای محتجب معظًم، ای متجلی به کرم، بادا روزی که باز رهم از زحمت حوا و آدم"}, {"id": "munajat-۱۳۲", "text": "الهی ای نزدیکتر به ما از ما، مهربانتر از ما بمه ما، نوازندهٔ ما بی ما"}, {"id": "munajat-۱۳۳", "text": "الهی ای حجت را یاد و انس را یادگار، خود حاضری ما را جُستن چه کار"}, {"id": "munajat-۱۳۴", "text": "الهی هر کسی را امیدی و امید رهی دیدار، رهی را بی دیدار نه به مُزد نیاز است نه به بهشت کار"}, {"id": "munajat-۱۳۵", "text": "الهی ای مهربان فریاد رس، عزیز آن کس که بها تو یک نفس"}, {"id": "munajat-۱۳۶", "text": "الهی یافته می جویم، با دیده ور میگویم چه جَویم که دارم، که بینم چه گویم"}, {"id": "munajat-۱۳۷", "text": "الهی تو موجود عارفانی، آرزوی دل مشقانانی، یاد آور زبان مدّاحانی"}, {"id": "munajat-۱۳۸", "text": "الهی تا بنده را خواندی بنده در میان مردم تنهاست و تا گفتی بیا هفت اندام او شنواست"}, {"id": "munajat-۱۳۹", "text": "الهی اگر کسی بترا بطلب یافت من خود طلب از تو یافتم، اگر کسی ترا به جُستن یافت من بگریختن یافتم"}, {"id": "munajat-۱۴۰", "text": "الهی چه شود که دلم را بگشایی و از خود مرهمی بر جانم نهی"}, {"id": "munajat-۱۴۱", "text": "الهی نسیمی از باغ دوستی دمید دل را فدا کردیم، بویی از حزینهٔ دوستی یافتیم به پادشاهی سر عالم ندا کردیم"}, {"id": "munajat-۱۴۲", "text": "الهی هر شادی که بی تو است اندوه است هر منزلی که نه در راه تو است زندان است هر دل که نه در طلب تو است ویران است"}, {"id": "munajat-۱۴۳", "text": "الهی چه زیباست ایام دوستان تو با تو و چه نیکو است معاملت ایشان در ارزوی دیدار تو"}, {"id": "munajat-۱۴۴", "text": "الهی آب عنایت تو بسنگ رسید، سنگ بار گرفت، از سنگ میوه رُست میوه طعم و مزه گرفت. پروردگارا یاد تو دل را زنده کرد و تخم مهر افگند، درخت شادی رویانید و میوه آزادی داد"}, {"id": "munajat-۱۴۵", "text": "الهی پهنای عزت تو جای اشارت نگذاشت و قدم و حدانیت تو راه اضافت برداشت تا رهی گم کرد آنچه در دست داشت و نا چیز شد هر چه می پنداشت"}, {"id": "munajat-۱۴۶", "text": "الهی مشرب می شناسم اما وا خوردن نمی یارم، دل تشنه و در آرزوی قطرهٔ میزارم سقایه مرا سیراب نکند، من در طلب دریایم، بر هزار چشمه گذر کردم تا که دریا دریابم"}, {"id": "munajat-۱۴۷", "text": "الهی غریب تو را غربت وطن است، کی هرگز بخانه رسد کسی که غربت او را وطن است"}, {"id": "munajat-۱۴۸", "text": "الهی مشتاق کُشتهٔ دوستی و کُشتهٔ دوست دیدار ترا کفن است"}, {"id": "munajat-۱۴۹", "text": "الهی چه خوش روزگاری است روزگار دوستان تو با تو، چه خوش بازاری است بازار عارفان در کار تو، چه آتشین است نَفسهای ایشان در یاد تو"}, {"id": "munajat-۱۵۰", "text": "الهی ای سزاوار ثنای خویش، ای شکر کنندهٔ عطای خویش ای شیرین نمایندهٔ بلای خویش، بنده به ذات خود از ثنای تو عاجز است"}, {"id": "munajat-۱۵۱", "text": "الهی گرفتار آن دردم که داروی آنی، بندهٔ آن ثنایم که توت سزاوار آنی، من در تو چه دانم؟ تو دانی"}, {"id": "munajat-۱۵۲", "text": "الهی چه یاد کنم که خود همه یادم، من خرمن نشان خود همه را فرا باد نهادم، بفضل خود ما را یاد کن و بیاد لطیفی ما را شاد کن"}, {"id": "munajat-۱۵۳", "text": "الهی جُز از شناخت و تو شادی نیست و جُز از یافت تو زندگانی نه، زندهٔ بی تو چون مُردهٔ زندانی است"}, {"id": "munajat-۱۵۴", "text": "الهی مران کسی را که خود خواندی، ظاهر مکن جُرمی را که پوشیدی، کریما میان ما و تو داور تویی"}, {"id": "munajat-۱۵۵", "text": "الهی اگر این آه از ما دعوی است تو سزای آنی، اگر لاف است بجای آنی اگر صدقست وفای آنی"}, {"id": "munajat-۱۵۶", "text": "الهی از سه چیز که دارم در یکی نگاه کن: اول بیخودی که جُز تو را از دل نخاست، دوم تصدیقی که هر چه گفتم راست، سوم چون با ذکرم خاست دل و جان جُز تو را نخواست"}, {"id": "munajat-۱۵۷", "text": "الهی از دو دعوی به زینهارم و از هر دو به فضل تو فریاد خواهم، از آنکه پندارم بخود چیزی دارم، یا پندارم که بر تو حقی دارم"}, {"id": "munajat-۱۵۸", "text": "الهی نزدیک نفسهای دوستانی، حاضر دل ذاکرانی، از نزدیک نشانت میدهند و بر تر از آنی"}, {"id": "munajat-۱۵۹", "text": "الهی کشیدید آنچه کشیدیم همه نوش گشت چون آوای قبول شنیدیم، دل رفت مبارک باد، گر جان برود در راه پسندیدیم"}, {"id": "munajat-۱۶۰", "text": "الهی آتش یافت با نور شناخت آمیختی و از باغ وصال نسیم قرب بر انگیختی با آتش دوستی آب گل سوختی"}, {"id": "munajat-۱۶۱", "text": "الهی عنایت تو کوه است و فضل تو دریا، کوه کی فرسود و دریا کی کاست، پس شادی یکی است که دوست یکتاست"}, {"id": "munajat-۱۶۲", "text": "الهی از کَرَم تو همین چشم داریم و از لطف تو همین گوش داریم بیامُرز ما را که بس آلوده ایم به کردار خویش"}, {"id": "munajat-۱۶۳", "text": "الهی تا آموختن را آموختم، آموخته را جمله بسوختم، اندوخته را بر انداختم و انداخته را بیندوختم"}, {"id": "munajat-۱۶۴", "text": "الهی تا یگانگی بشناختم، در آرزوی بگداختم، کی باشد که گویم پیمانه بینداختم"}, {"id": "munajat-۱۶۵", "text": "الهی گاه میگویی فرود آی، گاه میگویی بگُریز، گاه فرمایی بیا، گاه گویی بپرهیز، ای مهربان بُردبار، ای لطیف نیک بار"}, {"id": "munajat-۱۶۶", "text": "الهی این دل من کان حسرت است و تن من مایهٔ درد و غم، ما نه ارزانی بودیم تا ما را بر گزیدی و نه نا ارزانی بودیم که به غلط بر گزیدی"}, {"id": "munajat-۱۶۷", "text": "الهی تا مهر تو پیدا گشت همه مهر با جفا گشت و تا نیکی تو پیدا گشت همه جفا ها وفا گشت"}, {"id": "munajat-۱۶۸", "text": "الهی نامت نور دیدهٔ آشنایان، یادت آیین منزل مشتاقان، یافتنت چراغ دل مُریدان انست جان دوستان"}, {"id": "munajat-۱۶۹", "text": "الهی چه خوش روزی که خورشید جلالا تو به ما نظر میکند، چه خوش وقتی که مشتار از مشاهدهٔ جمال تو ما را خبری دهد"}, {"id": "munajat-۱۷۰", "text": "الهی نصیب این بیچاره از این کار همه درد است، مبارک باد که مرا این درد فرد است حاق که هر کس بدین درد ننازد جوانمرد است"}, {"id": "munajat-۱۷۱", "text": "الهی شاد بدانم که اول من نبودم تو بودی، آتش یافتنی با نور شناختن تو آمیختی، از باغ وصال نسیم قرب تو انگیختی"}, {"id": "munajat-۱۷۲", "text": "الهی جلال عزت تو جای اشارت نگذاشت و محو اثبات تو راه اضافت برداشت تا گم گشت آنچه بنده در دست داشت"}, {"id": "munajat-۱۷۳", "text": "الهی آن روز کجا باز یابم که تو مرا بودی و من نبودم، من کُجا بودم که تو مرا خواندی من نه منم که تو مرا ماندی"}, {"id": "munajat-۱۷۴", "text": "الهی مران کسی را که تو خود خواندی، آشکار مکن گناهی را که تو خود پوشیدی، اکنون که بر گرفتی مگذار و در سایهٔ لطف خود میدار"}, {"id": "munajat-۱۷۵", "text": "الهی آب عنایت تو به سنگ رسید، سنگ بار گرفت، سنگ درخت رویانید درخت میوه بار گرفت"}, {"id": "munajat-۱۷۶", "text": "الهی بنام تو زبانها گویا شده، بنام تو جانها شیدا شده، بیگانه آشنا شده، زشت ها زیبا شده، کار ها هویدا شده، راهها پیدا شده"}, {"id": "munajat-۱۷۷", "text": "الهی تو جانها اسیر پیغام تو، عارف افتاده بدام تو مشتاقان مست مهر از جام تو، خوشا بحال کسی که از این جام شربتی چشید"}, {"id": "munajat-۱۷۸", "text": "الهی از وجود تو هر مفلسی را نصیبی از کَرَم تو هر دردمندی را طبیبی است از سعت رحمت تو هر کسی را بهره ای"}, {"id": "munajat-۱۷۹", "text": "الهی این چه بد تر روزی است ترسم که مرا از تو جُز حسرت نه روزی است، خداوندا از بخت خود چون بپرهیزم"}, {"id": "munajat-۱۸۰", "text": "الهی کریما دل من کان حسرت است و تن من مایهٔ درد و غم نیارم گفت که اینهمه چرا بهمره من"}, {"id": "munajat-۱۸۱", "text": "الهی ای گشایندهٔ زبان مناجات گویان و انس افزای خلوتهای ذاکران و حاضر نفسهای راز داران"}, {"id": "munajat-۱۸۲", "text": "الهی دعوی صاقانی، فرزندهٔ نفسهای دوستانی، آرام دل غریبانی، چون در میان جان حاضری از بیدلی میگویم که کُجایی"}, {"id": "munajat-۱۸۳", "text": "الهی بهر صفت که هستم بر خواست تو موقوفم، به هر نام که مرا خوانند به بندگی تو معروفم"}, {"id": "munajat-۱۸۴", "text": "الهی اگر تو فضل کنی، دیگران چه داد و چه بیداد، و اگر تو عدل کنی فضل دیگرا چون باد"}, {"id": "munajat-۱۸۵", "text": "الهی چند نهان باشی و چند پیدا؟ که دلم حیران گشت و جان شیدا، تا کی در استتار و تجلی کیبود آن تجلی جاودانی"}, {"id": "munajat-۱۸۶", "text": "الهی این بوده و هست و بودنی، من بقدر شآن تو نادانم و سزای تو را نتوانم در بیچارگی خود گردانم"}, {"id": "munajat-۱۸۷", "text": "الهی روزگاری تو را می جستم خود را می یافتم، اکنون خود را می جویم تو را می یابم، چون حاضری این جستن بچه کار"}, {"id": "munajat-۱۸۸", "text": "الهی یافته می جویم، با دیده در میگویم که دارم چه جویم، که می بینم چه گویم؟ شیفتهٔ این جُست و جویم گرفتار این گفت و گویم"}, {"id": "munajat-۱۸۹", "text": "الهی به عنایت ازلی تخم هدایت کاشتی، به رسالت پیامبران آب دادی، به یاری و توفیق پروردی بنظر خود بار آوردی"}, {"id": "munajat-۱۹۰", "text": "الهی گاه گریم که در اختیار دیوم از بس تاریکی بینم، باز ناگاه نوری تابد که جملهٔ بشریت در جنب آن ناپدید بود"}, {"id": "munajat-۱۹۱", "text": "الهی تو در ازل ما را بر گرفتی و کسی نگفت که بردار، اکنون که بر گرفتی نه بگذار، و در سایهٔ لطف تو خود میدار"}, {"id": "munajat-۱۹۲", "text": "الهی آنچه نا خواسته یافتنی است، خواهندهٔ آن کیست؟ و آنچه از پاداش بر تر است پرسش در جنب آن چیست؟"}, {"id": "munajat-۱۹۳", "text": "الهی مرا دردی است که بهی مباد پس این درد مرا صواب است، با خرسندی دردمندی به درد خود کسی را چه حساب است"}, {"id": "munajat-۱۹۴", "text": "الهی گاهی بخود نگرم گویم از من زار تر کیست، گاهی به تو نگرم گویم از من بزرگوار تر کیست؟"}, {"id": "munajat-۱۹۵", "text": "الهی آمدم با دو دست تهی، سوختم به امید روز بهی، چه باشد اگر بر این دل خسته ام مرهم نهی"}, {"id": "munajat-۱۹۶", "text": "الهی از آرندهٔ غم پشیمانی در دلهای آشنایان، دستگیر که چون تو دستگیر نیست دریاب که جُز تو پناه نیست"}, {"id": "munajat-۱۹۷", "text": "الهی کار تو بی ما به نیکویی در گرفتی، چراغ خود را بی ما به مهربانی افروختی"}, {"id": "munajat-۱۹۸", "text": "الهی تو دوستان خود را به لطف پیدا گشتی تا قومی را بشراب انس مست کردی، قومی را به دریای دهشت غرق کردی"}, {"id": "munajat-۱۹۹", "text": "الهی تو آنی که نور تجلی بر دلهای دوستان تابان کردی و چشمه های مهر در سر ایشان روان کردی"}, {"id": "munajat-۲۰۰", "text": "الهی هر چه نشان می شمردم پرده بود و هر چه مایه می دانستم بهیده بود"}, {"id": "munajat-۲۰۱", "text": "الهی راهم نما بخود و باز رهان مرا از بنده خود، بار الها یاد تو عیش است و مهر تو سور"}, {"id": "munajat-۲۰۲", "text": "الهی نه جُز از شناخت تو شادی است نه جُز از یافت تو زندگانی، زندگانی بی تو، بردگی است"}, {"id": "munajat-۲۰۳", "text": "الهی ای یافته و یافتنی، از مست چه نشان دهند جُز بی خویشتنی، همه خلق را محنت از دوری است"}, {"id": "munajat-۲۰۴", "text": "الهی ای دانندهٔ هر چیز و سازندهٔ هر کار و دارندهٔ هر کس نه کس را با تو انبازی و نه کس را از تو بی نیازی"}, {"id": "munajat-۲۰۵", "text": "الهی به عنایت هدایت دادی و به معونت ها بذر خدمت رویانیدی و به پیغام آب پذیرش دادی"}, {"id": "munajat-۲۰۶", "text": "الهی تو آنی که از احاطت ادهام بیرونی و از ادراک عقول مصونی، در حکم بی چرا و در ذات بی چند و در صفات بی چونی"}, {"id": "munajat-۲۰۷", "text": "الهی نصیب این بیچاره از این کار همه درد است مُبارک باد که مرا این همه درد در خورد است"}, {"id": "munajat-۲۰۸", "text": "الهی در دل دوستان تو نور عنایت پیداست و جانها در آرزوی وصال تو حیران و شیداست، چون تو مولا کراست؟"}, {"id": "munajat-۲۰۹", "text": "الهی هر چه دادی نشان است و آیین فرداست و آنچه یافتیم پیغام است و خلعت بر جاست"}, {"id": "munajat-۲۱۰", "text": "الهی در ذات بی نظیری در صفات بی مانندی و گناهکاران را آمرزگاری و ایشانرا راز داری"}, {"id": "munajat-۲۱۱", "text": "الهی نالیدن من در درد از بیم زوال آنست که او که از زخم دوست بنالد در مهر دوست نامرد است"}, {"id": "munajat-۲۱۲", "text": "الهی آن کرده را بر سر کوی بلا آوردی و بلا و مُصیبتها را بایشان نمودی، یک گروه اندک روی گردان نشدند و عاشق وار سر به کوی بلا نهادند"}, {"id": "munajat-۲۱۳", "text": "الهی ای یادگار جانها و یاد رشتهٔ دلها، به فضل خود ما را یاد کن و بیاد لطفی ما را شاد کن"}, {"id": "munajat-۲۱۴", "text": "الهی تو به یاد خودی و من بیاد تو، تو بر خواست خودی و من بر نهاد تو"}, {"id": "munajat-۲۱۵", "text": "الهی ذکر تو بهرهٔ مشتاق است و روشنایی دیده و دولتی جان و آیین جهان، عزیز آن بنده که سزاوار آنست"}, {"id": "munajat-۲۱۶", "text": "الهی بقدر تو نادانم و سزای تو را ناتوانم در بیچارگی خود سرگردانم، روز بروز بر زیانم"}, {"id": "munajat-۲۱۷", "text": "الهی چون یتیم بی پدر گریانم، درمانده در دست خصمانم، خستهٔ گناهم و از خوزشتن بر تاوانم"}, {"id": "munajat-۲۱۸", "text": "الهی دریغا که روزگار بر باد دادیم و شکر نعمت ولی نعمت نگُذاردیم، دریغا که قدر عُمر خویشتن نشناختیم"}, {"id": "munajat-۲۱۹", "text": "الهی ای نا دریافته یافته و نا دیدهٔ عیان، ای در نهانی پیدا و در پیدایی نهان"}, {"id": "munajat-۲۲۰", "text": "الهی زندگی همه با یاد تو، شادی همه با یافت تو و جان آنست که در او شناخت تو است"}, {"id": "munajat-۲۲۱", "text": "الهی عظیم شانی و همیشه مهربانی، قدیم احسان و روشن برهانی هم نهانی هم عیانی"}, {"id": "munajat-۲۲۲", "text": "الهی او که حق بدلیل جوید به بیم و طمع پرستد او که حق را باحسان دوست دارد روز محنت برگردد"}, {"id": "munajat-۲۲۳", "text": "الهی عارف تو را به نور تو میداند و از شعاع وجود عبارت نمیتواند در آتش مهر می سوزد و از نار باز نمی پردازد"}, {"id": "munajat-۲۲۴", "text": "الهی تو آنی که از بنده نا سزا بینی و به عقوبت نشتابی، از بنده کفر می شنوی و نعمت از او باز نگیری"}, {"id": "munajat-۲۲۵", "text": "الهی در یافتی خود یاری و یادگاری، معنی دعوی صادقانی، فروزندهٔ نفسهای دوستانی آرام دل غریبانی"}, {"id": "munajat-۲۲۶", "text": "الهی به عنایت ازلی تخم هدایت کاشتی، به رسالت پیامبران آبدادی و بیاری توفیق رویانیدی"}, {"id": "munajat-۲۲۷", "text": "الهی وقت را بدرد مینازم و زیادتی را میسازم بامید آنکه چون در این درد بگذارم در دو راحت هر دو بر اندازم"}, {"id": "munajat-۲۲۸", "text": "الهی دوستان تو سران و سرهنگانند و بی گنچ و خواسته تو نگرانند و بنام درویشانند و بحقیقت توانگران جهان ایشانند"}, {"id": "munajat-۲۲۹", "text": "الهی هر چند از بد سزای خویش بدردم لیکن از مفلس نوازی تو شادم"}, {"id": "munajat-۲۳۰", "text": "الهی ای راهنما به کَرَم، فرو ماندم در حیرت یکدم آن کدام است؟ دمی که نه حوا در آن گنجد نه آدم"}, {"id": "munajat-۲۳۱", "text": "الهی از خود تو هر مفلسی را نصیبی و از کرم تو هر درد مندی را طبیبی و از وسعت رحمت تو هر کسی را سهمی است"}, {"id": "munajat-۲۳۲", "text": "الهی هر چند ما گُنه کاریم تو غفاری هر چند ما زشت کاریم تو ستاری"}, {"id": "munajat-۲۳۳", "text": "الهی به نشانت بینندگانیم به نامت زندگانیم، بفضلت شادانیم به مهرت نازانیم"}, {"id": "munajat-۲۳۴", "text": "الهی دانی که من به خود به این ورزم و نه بکفایت خود شمع هدایت افروزم، همه تویی من کیم اگر فضل تو نباشد من چه ام"}, {"id": "munajat-۲۳۵", "text": "الهی کدام زبان به ستایش تو رسد؟ کدام خرد صفت تو را بر تابد، کدام شکر با نیکویی تو برابر آید"}, {"id": "munajat-۲۳۶", "text": "الهی این سُوز امروز ما درد آمیز است، نه طاقت بسر بردن و نه جای گُریز است"}, {"id": "munajat-۲۳۷", "text": "الهی هر کس بر چیزی است و من ندانم بر چه ام، بیمم آنست که کی دانسته شود که من کیم"}, {"id": "munajat-۲۳۸", "text": "الهی این تن کان حسرت است و دل من مایهٔ درد و محنت، می نیارم گفت کاین هره چرا بهرهٔ من"}, {"id": "munajat-۲۳۹", "text": "الهی بقدر تو نادانم، سزای تو را ناتوانم، به بیچارگی خود سر گردانم و روزبروز در زیانم"}, {"id": "munajat-۲۴۰", "text": "الهی در دل دوستانت نور عنایت پیداست و جانها در آرزوی وصالت حیران و شیداست چون تو مولا کراست؟"}, {"id": "munajat-۲۴۱", "text": "الهی دوستدار از زبان خاموش است ولی حالش همه زبان است، خداوندا گناه من زیر حلم تو پنهان است تو پردهٔ عفو بر من گستران و مرا ببخش"}, {"id": "munajat-۲۴۲", "text": "الهی بود من بر من تاوان است، تو یک بار بود بر من تابان مصیبت من بر من گران است، تو آب خود بر من باران"}, {"id": "munajat-۲۴۳", "text": "الهی چون با خود نگرم و کردار خود بنم گویم از من زار تر کیست؟ و چون با تو نگرم گویم از من بزرگوار تر کیست"}, {"id": "munajat-۲۴۴", "text": "الهی گاهی که بخود می نگرم همه سوز و نیاز شوم و گاهی که با او نگرم همه راز و ناز شوم"}, {"id": "munajat-۲۴۵", "text": "الهی تو آنی که خود گفتی و چنانکه خود گفتی چنانی پس عضیم شانی و بزرگ احسانی، عزیز سلطانی"}, {"id": "munajat-۲۴۶", "text": "الهی آنچه بر سر ما آید بر سر کسی نیاید دیدهٔ که بنظارهٔ تو آید هرگز باز پس نیاید"}, {"id": "munajat-۲۴۷", "text": "الهی نظر خود بر ما مدام کن و ما را بر داشتهٔ خود نام کن و بوقت رفتن بر جان ما سلام کن"}, {"id": "munajat-۲۴۸", "text": "الهی فرمایی که بجوی و میترسانی که بگریز، مینمایی که بخواه و میگویی پرهیز"}, {"id": "munajat-۲۴۹", "text": "الهی زبانم در سر ذگر شد و ذکر سر مذکور، دل در سر مهر شد و مهر در سر نور جان در سر عیان شد از بیان دور"}, {"id": "munajat-۲۵۰", "text": "الهی نه نیستم نه هستم نه بریدم نه پیوستم نه بخود بیان بستم، لطیفهٔ بودم از آن مستم اکنون زیر سنگ است دستم"}, {"id": "munajat-۲۵۱", "text": "الهی گریخته بودم تو خواندی ترسیده بودم بر خوان نشاندی، اکنون میترسم که مرا بفریبی عطای خویش"}, {"id": "munajat-۲۵۲", "text": "الهی چون بدانستم که توانگری درویشی است دوست درویشم چون وعدهٔ دیدار دوست کردی غلام دیدهٔ خویشم"}, {"id": "munajat-۲۵۳", "text": "الهی چون ما را در حجرهٔ بی شمع و چراغ مبتلا کنند ایمان ما را تو چراغ لحد ما گردانی"}, {"id": "munajat-۲۵۴", "text": "الهی شادی نمی شناختم می پنداشتم که شادم اکنون مرا چه شادی که شادی شناسی را بباد دادم"}, {"id": "munajat-۲۵۵", "text": "الهی حاجت بسیار دارم و بر همه چیز توانایی آنچه میخواهم میتوانی که باین بنده برسانی و از شر ظالمان مرا برهانی"}, {"id": "munajat-۲۵۶", "text": "الهی چون عزیزان بناز پرورده ما را فراموش کنند تو بر ما رحمت کن"}, {"id": "munajat-۲۵۷", "text": "الهی غافلانیم نه کافرانیم، ببرکت نواختگان حضرت تو و ببرکت گُداختگان هیبت تو"}, {"id": "munajat-۲۵۸", "text": "الهی ببرکت متحیران جلال تو و ببرکت مقهوران قهر تو که ما را بصحرای هدایت آری"}, {"id": "munajat-۲۵۹", "text": "الهی دانی که بی تو هیچکسم، دستم گیر که در تو رسم، بظاهر قبول دارم بباطن تسلیم"}, {"id": "munajat-۲۶۰", "text": "الهی گر زارم، در تو زاریدن خوش است، ور نازم به تو نازیدن خوش است"}, {"id": "munajat-۲۶۱", "text": "الهی ما در دنیا معصیت میکردیم دوست تو مُحمد (ص) غمگین شود و دشمن تو ابلیس شاد"}, {"id": "munajat-۲۶۲", "text": "الهی ببرکت صدیقان درگاه تو، الهی ببرکت پاکان درگاه تو که حاجت این بیچارهٔ درمانده را و مهمات جمیع مومنین ومومنان را برآورده بگردانی"}];

