const NATAL_INTERP = {"sun": {"حمل": "هسته‌ی وجودت پر از انرژی و ابتکاره. دوست داری پیشقدم باشی و از رویارویی با چالش‌های تازه نمی‌ترسی. صداقت و صراحتت گاهی تند به‌نظر می‌رسه، ولی از ریشه‌ی شجاعتت میاد.", "ثور": "هویتت حول ثبات، آرامش و لذت‌های ملموس زندگی شکل گرفته. صبور و قابل‌اعتمادی، و وقتی تصمیم می‌گیری، به‌سختی از مسیرت منحرف می‌شی. زیبایی و راحتی برات اهمیت واقعی داره.", "جوزا": "ذهن کنجکاو و چندبعدی داری؛ همیشه دنبال اطلاعات، گفت‌وگو و تنوعی. انطباق‌پذیری بالاته، ولی گاهی نگه‌داشتن تمرکز روی یک مسیر برات چالش‌برانگیزه.", "سرطان": "هویتت عمیقاً با احساسات، خانواده و حس تعلق گره خورده. مراقب و باوفایی، حافظه‌ی احساسی قوی داری و از ریشه‌هات نیرو می‌گیری.", "اسد": "در مرکز وجودت یه نیاز اصیل به خلق‌کردن، درخشیدن و دیده‌شدن هست. سخاوتمند و باوقاری، و وقتی قلبت درگیر چیزی بشه، تمام‌قد پاش وایمیستی.", "سنبله": "هویتت حول دقت، خدمت و بهبود مستمر شکل گرفته. تحلیل‌گری و جزئیات رو می‌بینی که خیلیا از کنارش رد می‌شن؛ فقط مراقب باش زیادی سخت‌گیر خودت نباشی.", "میزان": "تعادل، زیبایی و ارتباط برات معنای هویتیه. توی روابط دوطرفه بهترین نسخه‌ی خودتی، و عدالت برات فقط یه ایده نیست، یه اصل زندگیه.", "عقرب": "هویتت با عمق، شدت و تحول گره خورده. از سطحی‌بودن بدت میاد و می‌خوای همه‌چیز رو تا ریشه بفهمی. قدرت درونی‌ت بیشتر از چیزیه که نشون می‌دی.", "قوس": "روحیه‌ی جستجوگر و آزادی‌خواه داری. معنا و افق‌های تازه (فکری، فرهنگی، جغرافیایی) هویتت رو می‌سازه. خوش‌بینی‌ت مسری‌ه.", "جدی": "هویتت حول هدف، مسئولیت و ساختن چیزی ماندگار شکل گرفته. صبور و بلندپروازی، و برای رسیدن به قله حاضری مسیر طولانی رو طی کنی.", "دلو": "فردیت و نوآوری بخش اصلی هویتته. دوست داری متفاوت فکر کنی و برای جمع بزرگ‌تر (نه فقط خودت) ارزش بسازی. استقلال فکری برات مقدسه.", "حوت": "هویتت سیال، شهودی و همدلانه‌ست. مرزهای بین خودت و دیگران رو کمرنگ حس می‌کنی، و دنیای درونی و خیالت غنیه."}, "moon": {"حمل": "احساساتت سریع و مستقیم بروز پیدا می‌کنن؛ عصبانیت یا شوق رو طولانی نگه نمی‌داری. برای آرامش درونی، نیاز به یه خروجی فعال (نه سکوت) داری.", "ثور": "دنیای احساسی‌ات به‌دنبال امنیت، آرامش و لذت‌های حسیه. تغییرات ناگهانی اذیتت می‌کنه؛ ثبات محیط برات مساوی آرامش روحیه.", "جوزا": "احساساتت رو بیشتر از راه حرف‌زدن و فکرکردن پردازش می‌کنی تا سکوت. نیاز داری درباره‌ی حس‌هات صحبت کنی تا واقعاً بفهمیشون.", "سرطان": "دنیای درونی‌ات عمیق و حساسه. خاطرات و پیوندهای عاطفی برات خیلی ماندگارن، و امنیت خانوادگی نیاز اصلی روحته.", "اسد": "احساساتت رو با شور و بزرگی زندگی می‌کنی. نیاز داری دیده و قدردانی بشی؛ وقتی این اتفاق نیفته، دلگیر می‌شی حتی اگه نگی.", "سنبله": "آرامش احساسی‌ات از طریق نظم، مفیدبودن و کنترل روی جزئیات به‌دست میاد. وقتی چیزی بی‌نظمه، حتی اگه ربطی بهت نداشته باشه، دلشوره می‌گیری.", "میزان": "نیاز عمیقی به هماهنگی و رابطه‌ی متعادل داری. تنش و دعوا احساسات رو برات آشفته می‌کنه؛ صلح درونی‌ات به کیفیت روابط اطرافت گره خورده.", "عقرب": "احساساتت شدید و لایه‌لایه‌ان؛ چیزی رو نصفه‌ونیمه حس نمی‌کنی. اعتماد برات به‌سختی به‌دست میاد ولی وقتی بیاد، عمیق و پایداره.", "قوس": "روحت برای آزادی و ماجراجویی می‌تپه. محدودشدن (حتی احساسی) برات سخته؛ خوش‌بینی درونی‌ات کمکت می‌کنه زود دوباره سرپا شی.", "جدی": "احساساتت رو با خویشتن‌داری نشون می‌دی، نه لزوماً بی‌احساسی. امنیت روانی‌ات از طریق پیشرفت و کنترل روی زندگی به‌دست میاد.", "دلو": "به احساساتت از یه فاصله‌ی فکری نگاه می‌کنی؛ گاهی دیگران این رو با سردی اشتباه می‌گیرن. نیاز داری فضای مستقل احساسی داشته باشی.", "حوت": "دنیای احساسی‌ات مثل اقیانوسه — عمیق، سیال و گاهی سخت برای مرزبندی. همدلی بالات هم هدیه‌ست هم گاهی خستت می‌کنه."}, "asc": {"حمل": "اولین برداشت دیگران ازت: پرانرژی، مستقیم و کمی بی‌تاب. طوری وارد اتاق می‌شی که انگار همیشه عجله داری به یه‌جایی برسی.", "ثور": "اولین برداشت دیگران ازت: آروم، قابل‌اعتماد و زمینی. حضورت حس امنیت و ثبات می‌ده، حتی قبل از اینکه حرفی بزنی.", "جوزا": "اولین برداشت دیگران ازت: باهوش، پرانرژی و اهل گفت‌وگو. زود یخ جمع رو می‌شکنی و کنجکاوی‌ات مسری‌ه.", "سرطان": "اولین برداشت دیگران ازت: مهربون، محتاط و کمی خجالتی در نگاه اول. مراقبت‌گری‌ات حتی توی برخورد اول دیده می‌شه.", "اسد": "اولین برداشت دیگران ازت: پراعتمادبه‌نفس، گرم و پرجذبه. حضورت به‌طور طبیعی توجه جمع رو به خودش می‌کشه.", "سنبله": "اولین برداشت دیگران ازت: منظم، دقیق و کمی رسمی. جدیت و توجه به جزئیاتت از همون نگاه اول حس می‌شه.", "میزان": "اولین برداشت دیگران ازت: خوش‌برخورد، متعادل و اجتماعی. طوری رفتار می‌کنی که همه احساس راحتی کنن.", "عقرب": "اولین برداشت دیگران ازت: مرموز، عمیق و پرقدرت. آدما حس می‌کنن یه‌چیزی پشت نگاهته که راحت نشونش نمی‌دی.", "قوس": "اولین برداشت دیگران ازت: بی‌خیال، صادق و پرانرژی. حس ماجراجویی و خوش‌بینی‌ات از فاصله هم دیده می‌شه.", "جدی": "اولین برداشت دیگران ازت: جدی، حرفه‌ای و قابل‌اتکا. حتی جوون‌ترین نسخه‌ی خودت هم یه پختگی خاصی نشون می‌ده.", "دلو": "اولین برداشت دیگران ازت: متفاوت، مستقل و کمی غیرقابل‌پیش‌بینی. زود می‌فهمن که قرار نیست مثل بقیه فکر کنی.", "حوت": "اولین برداشت دیگران ازت: ملایم، رویاگونه و دلرحم. یه چیزی توی نگاهت هست که آدما رو ناخودآگاه آروم می‌کنه."}};
